{% for assignment in attribute.assignment_person.first.person_assignments %}
    {% if assignment.status == "Active" %}
        {% if assignment.assignment_population.first.population_base_name == "Population1" %}
            {% assign sponsor1 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population2" %}
            {% assign sponsor2 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population3" %}
            {% assign sponsor3 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population4" %}
            {% assign sponsor4 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population5" %}
            {% assign sponsor5 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population6" %}
            {% assign sponsor6 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population7" %}
            {% assign sponsor7 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population8" %}
            {% assign sponsor8 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population9" %}
            {% assign sponsor9 = assignment.sponsor.first.login %}
        {% elsif assignment.assignment_population.first.population_base_name == "Population10" %}
            {% assign sponsor10 = assignment.sponsor.first.login %}
        {% endif %}
    {% endif %}
{% endfor %}
{
    "profile": {
        "attributes": {
            "person_risk_overall_score": "{{ attribute.person_risk_overall_score }}",
            "person_risk_probability_score": "{{ attribute.person_risk_probability_score }}",
            "person_risk_impact_score": "{{ attribute.person_risk_impact_score }}",
            "sponsor_login": "{% if sponsor1 %}{{ sponsor1 }}{% elsif sponsor2 %}{{ sponsor2 }}{% elsif sponsor3 %}{{ sponsor3 }}{% elsif sponsor4 %}{{ sponsor4 }}{% elsif sponsor5 %}{{ sponsor5 }}{% elsif sponsor6 %}{{ sponsor6 }}{% elsif sponsor7 %}{{ sponsor7 }}{% elsif sponsor8 %}{{ sponsor8 }}{% elsif sponsor9 %}{{ sponsor9 }}{% elsif sponsor10 %}{{ sponsor10 }}{% endif %}",
            "assignments_status_populations": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{ assignment.assignment_population.first.population_name }}|{% endfor %}",
            "assignments_status_organization": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{ assignment.assignment_organization.first.organization_name }}|{% endfor %}",
            "assignments_status_organization_suborganization": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{ assignment.assignment_organization.first.organization_name }},{{assignment.assignment_suborganization.first.suborganization_name}}|{% endfor %}",
            "assignments_status_population_department": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{ assignment.assignment_population.first.population_name }},{{assignment.assignment_department.first.department_code}}|{% endfor %}",
            "assignments_status_population_location": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{ assignment.assignment_population.first.population_name }},{{assignment.assignment_location.first.location_code}}|{% endfor %}",
            "assignments_status_location": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{assignment.assignment_location.first.location_code}}|{% endfor %}",
            "assignments_status_population_subpopulation": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{assignment.assignment_population.first.population_name}},{{assignment.assignment_subpopulation.first.subpopulation_name}}|{% endfor %}",
            "assignments_status_population_start_end_dates": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{assignment.assignment_population.first.population_name}},{{assignment.start_date}},{{assignment.end_date}}|{% endfor %}",
            "assignments_status_population_jobtitle": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{assignment.assignment_population.first.population_name}},{{assignment.job_title}}|{% endfor %}",
            "assignments_status_population_organization_suborganization": "{% for assignment in attribute.assignment_person.first.person_assignments %}|{{assignment.status }},{{assignment.assignment_population.first.population_name}},{{assignment.assignment_organization.first.organization_name}},{{assignment.assignment_suborganization.first.suborganization_name}}|{% endfor %}"
        }
    }
}

{% assign my_date = "now" | date: "%Y%m%d%H%M" %}
{% assign my_uid = profile.id | replace: "-", "" %}
{
    "roles": [
        {
            "uid": "{{ my_uid }}_{{ my_date }}_collaborators",
            "name": "{{ profile.name }} Collaborators",
            "groups": [
                "{{ profile.name }} Collaborators"
            ],
            "type": "NeaccessRole"
        }
    ]
}
